query:
query NavyMissingVariantDestroyEvents($after: String) {
  events(first: 50, after: $after, query: "subject_type:PRODUCT_VARIANT AND action:destroy AND created_at:>=2026-08-31 AND created_at:<2026-09-12 AND comments:false") {
    nodes { id action createdAt ... on BasicEvent { subjectId subjectType } }
    pageInfo { hasNextPage endCursor }
  }
}
